command:
cd /app && python3 - <<'PY'
p='parsing/html/writer.go'
s=open(p).read()
old='''	for _, child := range children {
		if child.tag == "" {
			if err := w.writeStructuredElement(buf, child.val, depth, true); err != nil {
				return err
			}
		} else {
			childDepth := depth + 1
			if mixed {
				childDepth = depth
			}
			if err := w.writeElement(buf, child.tag, child.val, childDepth, mixed || inline); err != nil {
				return err
			}
		}
	}'''
new='''	for _, child := range children {
		if child.tag == "" {
			if isStructuredNode(child.val) {
				if err := w.writeStructuredElement(buf, child.val, depth, true); err != nil {
					return err
				}
			} else if err := w.writeTopLevel(buf, child.val, depth); err != nil {
				return err
			}
			continue
		}
		childDepth := depth + 1
		if mixed {
			childDepth = depth
		}
		if err := w.writeElement(buf, child.tag, child.val, childDepth, mixed || inline); err != nil {
			return err
		}
	}'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
PY
gofmt -w parsing/html/writer.go && go test ./parsing/html/ 2>&1 | tail -5
